from __future__ import annotations

import hashlib
import json
import unicodedata
from typing import Final

NFC_FORM: Final[str] = "NFC"

GENESIS: Final[str] = "GENESIS"

_HASH_FIELDS: Final[tuple[str, ...]] = ("hash", "prev_hash")


def normalize_key(key: str) -> str:
    return unicodedata.normalize("NFC", key)


def canonical_bytes(line: dict) -> bytes:
    return json.dumps(
        line, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def line_hash(prev_hash: str, line: dict) -> str:
    without_hash_fields = {k: v for k, v in line.items() if k not in _HASH_FIELDS}
    payload = prev_hash.encode("utf-8") + b"|" + canonical_bytes(without_hash_fields)
    return hashlib.sha256(payload).hexdigest()

